-- Initial wedding schema; deployed to Supabase project vpqlgywiqsgiqmczsjrn.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,role text not null default 'admin' check(role in('super_admin','admin')),permissions jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.site_settings(id uuid primary key default gen_random_uuid(),setting_key text not null unique,value jsonb not null default '{}'::jsonb,is_public boolean not null default true,updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now());
create table public.content_pages(id uuid primary key default gen_random_uuid(),slug text not null unique,status text not null default 'draft' check(status in('draft','published','archived')),content jsonb not null default '{}'::jsonb,seo jsonb not null default '{}'::jsonb,updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.events(id uuid primary key default gen_random_uuid(),slug text not null unique,title jsonb not null default '{}'::jsonb,description jsonb not null default '{}'::jsonb,event_type text not null check(event_type in('wedding','reception','other')),starts_at timestamptz,ends_at timestamptz,venue_name text,venue_address text,maps_url text,sort_order integer not null default 0,is_published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.gallery_items(id uuid primary key default gen_random_uuid(),title jsonb not null default '{}'::jsonb,description jsonb not null default '{}'::jsonb,storage_path text not null,alt_text jsonb not null default '{}'::jsonb,sort_order integer not null default 0,is_published boolean not null default false,created_at timestamptz not null default now());
create table public.guests(id uuid primary key default gen_random_uuid(),full_name text not null,phone text,email text,household_label text,invite_code text unique,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.rsvps(id uuid primary key default gen_random_uuid(),guest_id uuid references public.guests(id) on delete set null,guest_name text not null,phone text,email text,attendance text not null check(attendance in('attending','not_attending','maybe')),party_size smallint not null default 1 check(party_size between 1 and 20),event_ids uuid[] not null default '{}',dietary_notes text,message text,preferred_language text not null default 'en' check(preferred_language in('en','gu','hi','mr')),whatsapp_consent boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid references auth.users(id) on delete set null,action text not null,entity_type text not null,entity_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index events_published_sort_idx on public.events(is_published,sort_order,starts_at);
create index gallery_published_sort_idx on public.gallery_items(is_published,sort_order);
create index rsvps_created_at_idx on public.rsvps(created_at desc);
create index rsvps_guest_id_idx on public.rsvps(guest_id);
create index audit_logs_created_at_idx on public.audit_logs(created_at desc);
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role in('super_admin','admin')); $$;
create function public.is_super_admin() returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='super_admin'); $$;
create function public.submit_rsvp(p_guest_name text,p_phone text,p_email text,p_attendance text,p_party_size integer,p_event_ids uuid[],p_dietary_notes text,p_message text,p_preferred_language text,p_whatsapp_consent boolean) returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid;
begin
 if length(trim(coalesce(p_guest_name,'')))<2 or length(p_guest_name)>120 then raise exception 'Please provide a valid name'; end if;
 if p_attendance not in('attending','not_attending','maybe') then raise exception 'Invalid attendance selection'; end if;
 if coalesce(p_party_size,0)<1 or p_party_size>20 then raise exception 'Party size must be between 1 and 20'; end if;
 if p_preferred_language not in('en','gu','hi','mr') then raise exception 'Unsupported language'; end if;
 if length(coalesce(p_message,''))>1000 or length(coalesce(p_dietary_notes,''))>500 then raise exception 'Message is too long'; end if;
 insert into public.rsvps(guest_name,phone,email,attendance,party_size,event_ids,dietary_notes,message,preferred_language,whatsapp_consent) values(trim(p_guest_name),nullif(trim(p_phone),''),nullif(trim(p_email),''),p_attendance,p_party_size,coalesce(p_event_ids,'{}'),nullif(trim(p_dietary_notes),''),nullif(trim(p_message),''),p_preferred_language,coalesce(p_whatsapp_consent,false)) returning id into v_id;
 return v_id;
end; $$;
revoke all on function public.submit_rsvp(text,text,text,text,integer,uuid[],text,text,text,boolean) from public;
grant execute on function public.submit_rsvp(text,text,text,text,integer,uuid[],text,text,text,boolean) to anon,authenticated;
alter table public.profiles enable row level security;
alter table public.site_settings enable row level security;
alter table public.content_pages enable row level security;
alter table public.events enable row level security;
alter table public.gallery_items enable row level security;
alter table public.guests enable row level security;
alter table public.rsvps enable row level security;
alter table public.audit_logs enable row level security;
create policy "Admins can read profiles" on public.profiles for select to authenticated using(public.is_admin() or id=(select auth.uid()));
create policy "Super admins manage profiles" on public.profiles for all to authenticated using(public.is_super_admin()) with check(public.is_super_admin());
create policy "Public reads public settings" on public.site_settings for select to anon,authenticated using(is_public or public.is_admin());
create policy "Admins manage settings" on public.site_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Public reads published pages" on public.content_pages for select to anon,authenticated using(status='published' or public.is_admin());
create policy "Admins manage pages" on public.content_pages for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Public reads published events" on public.events for select to anon,authenticated using(is_published or public.is_admin());
create policy "Admins manage events" on public.events for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Public reads published gallery" on public.gallery_items for select to anon,authenticated using(is_published or public.is_admin());
create policy "Admins manage gallery" on public.gallery_items for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Admins manage guests" on public.guests for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Admins read rsvps" on public.rsvps for select to authenticated using(public.is_admin());
create policy "Admins update rsvps" on public.rsvps for update to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Admins delete rsvps" on public.rsvps for delete to authenticated using(public.is_admin());
create policy "Admins read audit logs" on public.audit_logs for select to authenticated using(public.is_admin());
