create policy "Public can view wedding gallery assets" on storage.objects for select to anon,authenticated using(bucket_id='wedding-gallery');
create policy "Admins upload wedding gallery assets" on storage.objects for insert to authenticated with check(bucket_id='wedding-gallery' and public.is_admin());
create policy "Admins update wedding gallery assets" on storage.objects for update to authenticated using(bucket_id='wedding-gallery' and public.is_admin()) with check(bucket_id='wedding-gallery' and public.is_admin());
create policy "Admins delete wedding gallery assets" on storage.objects for delete to authenticated using(bucket_id='wedding-gallery' and public.is_admin());